-- seed 418 :: de translations 361-380

INSERT INTO translation_intake (original, locale, body) VALUES
    ('The only way to make sense out of change is to plunge into it, move with it, and join the dance.', 'de',
     'Der einzige Weg, Veränderung zu verstehen, ist, sich hineinzustürzen, sich mit ihr zu bewegen und mitzutanzen.'),
    ('Life is like riding a bicycle. To keep your balance you must keep moving.', 'de',
     'Das Leben ist wie Fahrradfahren. Um die Balance zu halten, musst du in Bewegung bleiben.'),
    ('They always say time changes things, but you actually have to change them yourself.', 'de',
     'Man sagt immer, die Zeit verändere die Dinge, aber eigentlich muss man sie selbst verändern.'),
    ('Progress is impossible without change, and those who cannot change their minds cannot change anything.', 'de',
     'Fortschritt ist unmöglich ohne Veränderung, und wer seine Meinung nicht ändern kann, kann gar nichts ändern.'),
    ('Change is the law of life. And those who look only to the past or present are certain to miss the future.', 'de',
     'Veränderung ist das Gesetz des Lebens. Und wer nur auf die Vergangenheit oder die Gegenwart blickt, wird die Zukunft verpassen.'),
    ('The secret of change is to focus all of your energy not on fighting the old, but on building the new.', 'de',
     'Das Geheimnis der Veränderung besteht darin, all deine Energie nicht auf den Kampf gegen das Alte zu richten, sondern auf den Aufbau des Neuen.'),
    ('What you get by achieving your goals is not as important as what you become by achieving your goals.', 'de',
     'Was du durch das Erreichen deiner Ziele bekommst, ist nicht so wichtig wie das, was du durch das Erreichen deiner Ziele wirst.'),
    ('Growth is painful. Change is painful. But nothing is as painful as staying stuck somewhere you don''t belong.', 'de',
     'Wachsen tut weh. Veränderung tut weh. Aber nichts tut so weh, wie irgendwo festzustecken, wo man nicht hingehört.'),
    ('And the day came when the risk to remain tight in a bud was more painful than the risk it took to blossom.', 'de',
     'Und der Tag kam, an dem das Risiko, eine fest verschlossene Knospe zu bleiben, schmerzhafter war als das Risiko zu erblühen.'),
    ('I am always doing that which I cannot do, in order that I may learn how to do it.', 'de',
     'Ich tue immer das, was ich nicht kann, um zu lernen, wie es geht.'),
    ('Unless you try to do something beyond what you have already mastered, you will never grow.', 'de',
     'Wenn du nicht versuchst, etwas zu tun, das über das hinausgeht, was du schon beherrschst, wirst du nie wachsen.'),
    ('We know what we are, but know not what we may be.', 'de',
     'Wir wissen, was wir sind, aber nicht, was wir werden können.'),
    ('Our doubts are traitors, and make us lose the good we oft might win, by fearing to attempt.', 'de',
     'Unsere Zweifel sind Verräter und lassen uns das Gute verlieren, das wir oft gewinnen könnten, weil wir den Versuch fürchten.');
